@RunWith(MockitoJUnitRunner.class)
public class AmbiguateProperties_process_TriageGen2Test {

    private AmbiguateProperties ambiguateProperties;

    @Mock
    private Compiler compiler;

    @Mock
    private Node externs;

    @Mock
    private Node root;

    @Before
    public void setUp() throws Exception {
        ambiguateProperties = new AmbiguateProperties(compiler);
        // Using reflection or providing a way to inject dependencies if they are private.
        // Since I cannot modify the source, I assume these fields are accessible 
        // via reflection or are package-private for testing.
        // For the sake of this test, we assume the internal state can be manipulated.
    }

    @Test
    public void testProcess_FullFlow_RenamesProperties() {
        try (MockedStatic<NodeTraversal> nodeTraversalMock = Mockito.mockStatic(NodeTraversal.class)) {
            // Setup internal state via reflection to simulate the class state
            injectField("externedNames", new HashSet<String>());
            injectField("quotedNames", new HashSet<String>());
            injectField("reservedCharacters", "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");
            injectField("stringNodesToRename", Lists.newArrayList());
            injectField("colorMap", new HashMap<Integer, String>());
            injectField("renamingMap", new HashMap<String, String>());

            // Create Property objects
            AmbiguateProperties.Property p1 = new AmbiguateProperties.Property("prop1", "type1");
            p1.skipAmbiguating = false;

            Map<String, AmbiguateProperties.Property> propertyMap = new HashMap<>();
            propertyMap.put("prop1", p1);
            injectField("propertyMap", propertyMap);

            // Mock Node for string renaming
            Node mockNode = mock(Node.class);
            when(mockNode.getString()).thenReturn("prop1");
            injectField("stringNodesToRename", Lists.newArrayList(mockNode));

            // Execute
            ambiguateProperties.process(externs, root);

            // Verify
            nodeTraversalMock.verify(() -> NodeTraversal.traverse(eq(compiler), eq(externs), any()));
            nodeTraversalMock.verify(() -> NodeTraversal.traverse(eq(compiler), eq(root), any()));
            verify(compiler, atLeastOnce()).reportCodeChange();

            assertThat(p1.newName).isNotNull();
            assertThat(p1.newName).isNotEqualTo("prop1");
            verify(mockNode).setString(p1.newName);
        }
    }

    @Test
    public void testProcess_WithSkippedProperties() {
        try (MockedStatic<NodeTraversal> nodeTraversalMock = Mockito.mockStatic(NodeTraversal.class)) {
            injectField("externedNames", new HashSet<String>(Collections.singletonList("ext")));
            injectField("quotedNames", new HashSet<String>(Collections.singletonList("quot")));
            injectField("reservedCharacters", "abc");
            injectField("stringNodesToRename", Lists.newArrayList());
            injectField("colorMap", new HashMap<Integer, String>());
            injectField("renamingMap", new HashMap<String, String>());

            // Property 1: To be renamed
            AmbiguateProperties.Property p1 = new AmbiguateProperties.Property("p1", "t1");
            p1.skipAmbiguating = false;

            // Property 2: To be skipped
            AmbiguateProperties.Property p2 = new AmbiguateProperties.Property("p2", "t2");
            p2.skipAmbiguating = true;

            Map<String, AmbiguateProperties.Property> propertyMap = new HashMap<>();
            propertyMap.put("p1", p1);
            propertyMap.put("p2", p2);
            injectField("propertyMap", propertyMap);

            ambiguateProperties.process(externs, root);

            // p2.oldName ("p2") should be added to reservedNames, 
            // effectively preventing p1 from being renamed to "p2"
            assertThat(p1.newName).isNotNull();
            assertThat(p1.newName).isNotEqualTo("p2");
        }
    }

    @Test
    public void testProcess_NoRenamingNeeded() {
        try (MockedStatic<NodeTraversal> nodeTraversalMock = Mockito.mockStatic(NodeTraversal.class)) {
            injectField("externedNames", new HashSet<String>());
            injectField("quotedNames", new HashSet<String>());
            injectField("reservedCharacters", "abc");
            injectField("stringNodesToRename", Lists.newArrayList());
            injectField("colorMap", new HashMap<Integer, String>());
            injectField("renamingMap", new HashMap<String, String>());

            // Property already has a name that doesn't conflict 
            // (Simulating numNewPropertyNames = 0 via empty graph logic)
            // Note: In actual logic, if graph is empty, numNewPropertyNames is 0.
            Map<String, AmbiguateProperties.Property> propertyMap = new HashMap<>();
            injectField("propertyMap", propertyMap);

            ambiguateProperties.process(externs, root);

            verify(compiler, Mockito.never()).reportCodeChange();
        }
    }

    @Test
    public void testProcess_StringNodeNotPresentInMap() {
        try (MockedStatic<NodeTraversal> nodeTraversalMock = Mockito.mockStatic(NodeTraversal.class)) {
            injectField("externedNames", new HashSet<String>());
            injectField("quotedNames", new HashSet<String>());
            injectField("reservedCharacters", "abc");
            injectField("colorMap", new HashMap<Integer, String>());
            injectField("renamingMap", new HashMap<String, String>());

            Node mockNode = mock(Node.class);
            when(mockNode.getString()).thenReturn("unknown");
            injectField("stringNodesToRename", Lists.newArrayList(mockNode));
            injectField("propertyMap", new HashMap<String, AmbiguateProperties.Property>());

            ambiguateProperties.process(externs, root);

            verify(mockNode, Mockito.never()).setString(any());
            verify(compiler, Mockito.never()).reportCodeChange();
        }
    }

    // Helper to inject private fields for testing purposes
    private void injectField(String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = AmbiguateProperties.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(ambiguateProperties, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private <T> T eq(T value) {
        return Mockito.eq(value);
    }
}
